import json, os, glob, re, sys, time, collections, statistics
C = '/skogai/claude'
PROJ = '/home/skogix/skogai-rpg'
out = {}

def load(p):
    try:
        return json.load(open(p))
    except Exception as e:
        return None

us = load(f'{C}/settings.json') or {}
ps = load(f'{PROJ}/.claude/settings.json') or {}
gj = load(f'{C}/.claude.json') or {}

out['user_settings_keys'] = sorted(us.keys())
out['user'] = {
    'defaultMode': us.get('permissions', {}).get('defaultMode'),
    'disableAutoMode': us.get('permissions', {}).get('disableAutoMode', us.get('disableAutoMode')),
    'autoUpdatesChannel': us.get('autoUpdatesChannel'),
    'enabledPlugins': us.get('enabledPlugins'),
    'skillOverrides': us.get('skillOverrides'),
    'allow': us.get('permissions', {}).get('allow'),
    'denyN': len(us.get('permissions', {}).get('deny', []) or []),
    'ask': us.get('permissions', {}).get('ask'),
    'envKeys': sorted((us.get('env') or {}).keys()),
}
hooks = []
for src, s in (('user', us), ('project', ps)):
    for ev, groups in (s.get('hooks') or {}).items():
        for g in groups:
            for h in g.get('hooks', []):
                hooks.append({'src': src, 'event': ev, 'matcher': g.get('matcher'), 'type': h.get('type'),
                              'async': h.get('async'), 'timeout': h.get('timeout'),
                              'cmd': (h.get('command') or '')[:200]})
out['hooks'] = hooks
out['project_settings'] = {'keys': sorted(ps.keys()), 'perm_keys': sorted((ps.get('permissions') or {}).keys()),
                           'defaultMode': (ps.get('permissions') or {}).get('defaultMode'),
                           'allow': (ps.get('permissions') or {}).get('allow')}
out['global'] = {'installMethod': gj.get('installMethod'), 'autoUpdates': gj.get('autoUpdates'),
                 'numStartups': gj.get('numStartups'), 'skillUsage': gj.get('skillUsage'),
                 'pluginUsage': gj.get('pluginUsage'), 'mcpServers': sorted((gj.get('mcpServers') or {}).keys()),
                 'mcp_alwaysLoad': {k: v.get('alwaysLoad') for k, v in (gj.get('mcpServers') or {}).items()},
                 'proj': {k: v for k, v in ((gj.get('projects') or {}).get(PROJ) or {}).items()
                          if k in ('disabledMcpServers', 'enabledMcpjsonServers', 'disabledMcpjsonServers')}}

# plugins installed
ip = load(f'{C}/plugins/installed_plugins.json') or {}
out['installed_plugins'] = {k: [{'scope': i.get('scope'), 'path': i.get('installPath'), 'projectPath': i.get('projectPath')} for i in v]
                            for k, v in (ip.get('plugins') or {}).items()}

def fm(path):
    try:
        t = open(path, errors='replace').read()
    except Exception:
        return None, 0
    m = re.match(r'^---\n(.*?)\n---', t, re.S)
    return (m.group(1) if m else None), len(t)

def desc_len(front):
    if not front: return 0
    n = 0; d = re.search(r'^description:\s*(.*?)(?=^\w[\w-]*:|\Z)', front, re.S | re.M)
    nm = re.search(r'^name:\s*(.*)$', front, re.M)
    return (len(d.group(1)) if d else 0) + (len(nm.group(1)) if nm else 0)

# skills listing estimate per plugin
plug_info = {}
for key, insts in out['installed_plugins'].items():
    for inst in insts:
        p = inst['path']
        if not p or not os.path.isdir(p): continue
        sk = glob.glob(f'{p}/skills/*/SKILL.md') + glob.glob(f'{p}/commands/**/*.md', recursive=True)
        ag = glob.glob(f'{p}/agents/*.md')
        chars = sum(desc_len(fm(f)[0]) for f in sk)
        agchars = sum(desc_len(fm(f)[0]) for f in ag)
        has = {d: os.path.exists(f'{p}/{d}') for d in ('hooks', '.mcp.json', 'skills', 'commands', 'agents', 'monitors', 'output-styles', 'themes', 'rules')}
        plug_info[key] = {'scope': inst['scope'], 'projectPath': inst.get('projectPath'), 'skills': [os.path.basename(os.path.dirname(f)) if f.endswith('SKILL.md') else os.path.basename(f)[:-3] for f in sk],
                          'agents': [os.path.basename(f)[:-3] for f in ag],
                          'listing_est_tokens': (chars + agchars) // 4, 'has': has}
out['plugin_info'] = plug_info

# user skills
us_sk = {}
for f in glob.glob(f'{C}/skills/*/SKILL.md'):
    front, n = fm(f)
    ok = True
    if front is not None:
        try:
            import yaml
            yaml.safe_load(front)
        except ImportError:
            ok = 'noyaml'
        except Exception as e:
            ok = f'PARSE ERROR: {str(e)[:120]}'
    else:
        ok = 'no frontmatter'
    us_sk[os.path.basename(os.path.dirname(f))] = {'est_tokens': desc_len(front) // 4, 'fm': ok}
out['user_skills'] = us_sk
for d in (f'{C}/agents', f'{PROJ}/.claude/agents', f'{PROJ}/.claude/skills'):
    out['exists_' + d] = os.path.isdir(d)

# CLAUDE.md sizes
mds = {}
for f in [f'{C}/CLAUDE.md', f'{PROJ}/CLAUDE.md', f'{PROJ}/SKOGAI.md', f'{PROJ}/HANDOVER.md', f'{PROJ}/AGENTS.md', f'{PROJ}/CLAUDE.local.md', f'{PROJ}/.claude/CLAUDE.md', '/home/skogix/CLAUDE.local.md', '/home/CLAUDE.local.md', f'{C}/RTK.md']:
    if os.path.exists(f):
        mds[f] = os.path.getsize(f)
mds['nested'] = [p for p in glob.glob(f'{PROJ}/**/CLAUDE.md', recursive=True) if p != f'{PROJ}/CLAUDE.md']
out['claude_md'] = mds

# transcripts
files = sorted(glob.glob(f'{C}/projects/*/*.jsonl'), key=os.path.getmtime, reverse=True)[:50]
out['window'] = {'n': len(files), 'oldest': time.strftime('%Y-%m-%d', time.localtime(os.path.getmtime(files[-1]))) if files else None,
                 'newest': time.strftime('%Y-%m-%d', time.localtime(os.path.getmtime(files[0]))) if files else None}
skill_hits = collections.Counter(); mcp_hits = collections.Counter(); slash = collections.Counter(); agent_types = collections.Counter()
hook_d = collections.defaultdict(list); hook_status = collections.Counter(); hook_timeouts = collections.Counter()
denials = collections.Counter(); denial_kinds = collections.defaultdict(collections.Counter)
tool_names = collections.Counter()
for f in files:
    uses = {}
    pend = []
    for line in open(f, errors='replace'):
        try: o = json.loads(line)
        except Exception: continue
        t = o.get('type')
        if t == 'assistant':
            for c in (o.get('message') or {}).get('content') or []:
                if isinstance(c, dict) and c.get('type') == 'tool_use':
                    n = c.get('name') or ''
                    tool_names[n] += 1
                    inp = c.get('input') or {}
                    uses[c.get('id')] = (n, inp)
                    if n == 'Skill': skill_hits[str(inp.get('skill'))[:80]] += 1
                    if n.startswith('mcp__'): mcp_hits[n.split('__')[1]] += 1
                    if n in ('Agent', 'Task'): agent_types[str(inp.get('subagent_type'))[:60]] += 1
        elif t == 'user':
            msg = o.get('message') or {}
            cont = msg.get('content')
            s = cont if isinstance(cont, str) else json.dumps(cont)[:4000] if cont else ''
            for m in re.findall(r'<command-name>/?([^<]{1,80})</command-name>', s): slash[m] += 1
            k = o.get('toolDenialKind')
            if k and k not in ('interrupted', 'cancelled') and isinstance(cont, list):
                for c in cont:
                    if isinstance(c, dict) and c.get('type') == 'tool_result':
                        pend.append((c.get('tool_use_id'), k))
        elif t == 'attachment':
            a = o.get('attachment') or {}
            if str(a.get('type', '')).startswith('hook_'):
                key = (a.get('hookEvent'), str(a.get('hookName'))[:60], str(a.get('command'))[:90])
                hook_status[(key, a.get('type'))] += 1
                if isinstance(a.get('durationMs'), (int, float)): hook_d[key].append(a['durationMs'])
                if a.get('timedOut'): hook_timeouts[key] += 1
    for tid, k in pend:
        n, inp = uses.get(tid, ('?', {}))
        if n == 'Bash':
            words = str(inp.get('command', '')).strip().split()
            pat = 'Bash: ' + ' '.join(words[:2])[:60]
        else:
            pat = n
        denials[pat] += 1; denial_kinds[pat][k] += 1
out['skill_hits'] = dict(skill_hits.most_common()); out['mcp_hits'] = dict(mcp_hits)
out['slash'] = dict(slash.most_common(40)); out['agent_types'] = dict(agent_types)
out['hooks_timing'] = [{'key': list(k), 'n': len(v), 'median': statistics.median(v), 'max': max(v)} for k, v in hook_d.items()]
out['hook_status'] = [[list(k), s, n] for (k, s), n in hook_status.items()]
out['hook_timeouts'] = [[list(k), n] for k, n in hook_timeouts.items()]
out['denials'] = [[p, n, dict(denial_kinds[p])] for p, n in denials.most_common(25)]
out['top_tools'] = dict(tool_names.most_common(25))
json.dump(out, open(sys.argv[1], 'w'), indent=1, default=str)
print('ok')

